WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_eng_c_ratio'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '效率比求解', 'kp-eng-c-ratio', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "效率比求解"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "题目直接给出或暗示了效率之间的比例关系。此时不需要找时间公倍数，而是直接赋值效率！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题干中出现“甲的效率是乙的2倍”、“甲乙效率之比为3:4”或者“2台A型机器等于3台B型机器的工作量”。特征是【只字不提单独完工的具体时间】。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "只要看到效率比，立刻在题目上圈出来，并写下具体的数字赋给 P。"}]}, {"type": "katexBlock", "attrs": {"content": "若 P_A : P_B = a : b, \\quad \\text{直接令 } P_A = a, P_B = b"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题目找到效率比例关系] --> B[直接赋予效率具体数值 P]\nB --> C[利用给出的合作/单干时间, 算出工程总量 W = P总 * T]\nC --> D[有了 W 和每个人的 P, 任何问题迎刃而解]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 甲乙效率比为 3:2，两人合作 6 天完成。若由甲单独做需要几天？选项：A. 10  B. 12  C. 15  D. 18"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "赋效率：看到 3:2，直接令 P甲 = 3，P乙 = 2。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "求总量：两人合作效率为 P合 = 3 + 2 = 5。合作了 6 天，所以总量 W = 5 × 6 = 30。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "解目标：甲单独做，T = W ÷ P甲 = 30 ÷ 3 = 10 天。选 A。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "生搬硬套时间公倍数：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "有些同学学傻了，看到工程问题就满世界找时间求公倍数。这题根本没有给各自的单干时间！记住：给时间，赋总量；给比例，赋效率。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "训练等量关系转化：看到“3个师傅的活等于5个徒弟的活”，脑子里一秒钟反应出“师:徒 = 5:3”，直接赋值。"}]}]}$$ AS jsonb), NULL, '效率比求解的核心考点与实战推导。', category_node.id, CAST('["数量关系", "工程问题", "效率比求解"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_eng_c_ratio", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
